#[allow(clippy::too_many_arguments)]
pub async fn get_page<C>(
  db: &C, game_id: i64, page: u64, page_size: u64, min_state: Option<State>,
  institute_id: Option<i64>, filter: Option<String>, order_by: Option<String>, asc: bool,
) -> Result<(Vec<Model>, u64), DbErr>
where
  C: ConnectionTrait, {
  let page_size = Ord::max(page_size, 1);
  let page = Ord::max(page, 1);
  let state = min_state.unwrap_or(State::Passed);
  let mut sql = Entity::find()
    .filter(Column::GameId.eq(game_id))
    .filter(Column::State.gte(state));
  let member_team_ids = get_member_team_ids(db, filter.as_deref()).await?;
  sql = filter_sql(sql, filter, member_team_ids)?;
  if let Some(institute_id) = institute_id {
    sql = sql.filter(Column::InstituteId.eq(institute_id));
  }
  if let Some(order_by) = order_by {
    let order_by = Column::from_str(order_by.as_str())
      .map_err(|e| DbErr::Custom(format!("invalid order_by: {e}")))?;
    sql = if asc {
      sql.order_by(order_by, Order::Asc)
    } else {
      sql.order_by(order_by, Order::Desc)
    };
  }
  sql = sql.order_by(Column::LastActiveAt, Order::Asc);
  let paginator = sql.into_model().paginate(db, page_size);
  let total = paginator.num_items().await?;
  let teams = paginator.fetch_page(page - 1).await?;
  Ok((teams, total))
}

#[allow(clippy::too_many_arguments)]
pub async fn get_page_by_tag<C>(
  db: &C, game_id: i64, page: u64, page_size: u64, min_state: Option<State>,
  institute_id: Option<i64>, tag: &str, filter: Option<String>,
) -> Result<(Vec<Model>, u64), DbErr>
where
  C: ConnectionTrait, {
  let state = min_state.unwrap_or(State::Passed);
  let mut teams = Entity::find()
    .filter(Column::GameId.eq(game_id))
    .filter(Column::State.gte(state));
  if let Some(institute_id) = institute_id {
    teams = teams.filter(Column::InstituteId.eq(institute_id));
  }
  let member_team_ids = get_member_team_ids(db, filter.as_deref()).await?;
  let mut teams = teams.all(db).await?;
  if let Some(filter) = filter {
    let filter = filter.to_ascii_lowercase();
    teams.retain(|team| {
      team.name.to_ascii_lowercase().contains(&filter)
        || member_team_ids
          .as_ref()
          .is_some_and(|ids| ids.contains(&team.id))
    });
  }
  let challenges = challenge::get_full_list(db, game_id).await?;
  let challenge_ids: HashSet<i64> = challenges
    .iter()
    .filter(|challenge| challenge.tag.contains_name(tag))
    .map(|challenge| challenge.id)
    .collect();
  let submissions =
    submission::get_list(db, true, false, Some(game_id), None, None, None, false).await?;
  let mut scores = HashMap::<i64, i32>::new();
  for submission in submissions {
    if challenge_ids.contains(&submission.challenge_id)
      && let Some(team_id) = submission.team_id
    {
      *scores.entry(team_id).or_default() += submission.score;
    }
  }
  for team in &teams {
    for extra in extra::get_list(db, team.id).await? {
      if extra
        .challenge_id
        .is_some_and(|id| challenge_ids.contains(&id))
      {
        *scores.entry(team.id).or_default() += extra.score;
      }
    }
  }
  for team in &mut teams {
    team.score = scores.get(&team.id).copied().unwrap_or_default();
  }
  teams.sort_by_key(|team| (std::cmp::Reverse(team.score), team.last_active_at));
  let total = teams.len() as u64;
  let page_size = Ord::max(page_size, 1) as usize;
  let page = Ord::max(page, 1) as usize;
  let start = (page - 1).saturating_mul(page_size);
  let paged = teams.into_iter().skip(start).take(page_size).collect();
  Ok((paged, total))
}

