pub async fn calc_score<C>(db: &C, id: i64) -> Result<i32, DbErr>
where
  C: ConnectionTrait, {
  let solves =
    super::submission::get_list(db, true, false, None, None, Some(id), None, false).await?;
  let score: i32 = solves.iter().map(|s| s.score).sum();
  let extras = super::extra::get_list(db, id).await?;
  let extra_score: i32 = extras.iter().map(|e| e.score).sum();
  let milestone_score = if let Some(team) = get(db, id).await? {
    let milestones = super::challenge_milestone::get_list(db, team.game_id).await?;
    let solved: HashSet<i64> = solves.iter().map(|s| s.challenge_id).collect();
    super::challenge_milestone::milestone_bonus(&solved, &milestones)
  } else {
    0
  };
  let total = score + extra_score + milestone_score;
  Ok(total)
}

pub async fn count_rank<C>(
  db: &C, game_id: i64, score: i32, last_active_at: DateTime<Utc>, with_hidden: bool,
) -> Result<i64, DbErr>
where
  C: ConnectionTrait, {
  let count = Entity::find()
    .filter(Column::GameId.eq(game_id))
    .filter(Column::State.gte(if with_hidden {
      State::Hidden
    } else {
      State::Passed
    }))
    .filter(
      Condition::any().add(Column::Score.gt(score)).add(
        Condition::all()
          .add(Column::Score.eq(score))
          .add(Column::LastActiveAt.lt(last_active_at)),
      ),
    )
    .count(db)
    .await?;
  Ok(count as i64 + 1)
}
